package com.interviewcoach.config;
import com.interviewcoach.repo.*;import com.interviewcoach.model.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.cors.*;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();}
 public static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Bean SecurityFilterChain chain(org.springframework.security.config.annotation.web.builders.HttpSecurity http,AuthTokenRepo tokens,@Value("${app.cors-origin}") String origin)throws Exception{
  OncePerRequestFilter bearer=new OncePerRequestFilter(){@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String header=req.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer ")){tokens.findByTokenHash(hash(header.substring(7))).filter(t->t.expiresAt.isAfter(Instant.now())).ifPresent(t->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(t.user.id,null,List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_USER")))));}chain.doFilter(req,res);}};
  http.csrf(c->c.disable()).cors(c->c.configurationSource(r->{CorsConfiguration v=new CorsConfiguration();v.setAllowedOrigins(List.of(origin));v.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));v.setAllowedHeaders(List.of("Authorization","Content-Type"));return v;})).sessionManagement(c->c.sessionCreationPolicy(org.springframework.security.config.http.SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.dispatcherTypeMatchers(DispatcherType.ERROR).permitAll().requestMatchers("/error","/api/auth/**","/actuator/health","/swagger-ui/**","/v3/api-docs/**").permitAll().anyRequest().authenticated()).addFilterBefore(bearer,UsernamePasswordAuthenticationFilter.class);return http.build();}
}
